import { bisector } from 'd3-array';

import type { TimeSeriesPoint } from './time-series-chart.data';

/**
 * One aggregated bucket — the same min / average / max shape Cognite Data
 * Fusion returns for datapoint aggregates.
 */
export interface TimeSeriesBucket {
  /** Bucket midpoint, epoch milliseconds. */
  t: number;
  min: number;
  max: number;
  average: number;
  count: number;
}

export interface AggregateResult {
  buckets: TimeSeriesBucket[];
  /** Raw points that fell inside the visible window. */
  rawCount: number;
  /** Milliseconds covered by each bucket; 0 when raw points are returned. */
  granularity: number;
}

const byTime = bisector<TimeSeriesPoint, number>((point) => point.t);

/**
 * Level-of-detail downsampling. Slices the visible window with a binary
 * search, then folds points into at most `maxBuckets` equal time buckets.
 * When the window holds fewer points than buckets, raw points come back
 * unchanged so zooming in reveals every reading.
 *
 * One neighbour on either side of the window is kept so lines run to the
 * plot edge instead of stopping at the first visible point.
 */
export function aggregateSeries(
  points: TimeSeriesPoint[],
  [start, end]: [number, number],
  maxBuckets: number
): AggregateResult {
  const from = Math.max(0, byTime.left(points, start) - 1);
  const to = Math.min(points.length, byTime.right(points, end) + 1);
  const visible = points.slice(from, to);
  const bucketCount = Math.max(1, Math.floor(maxBuckets));

  if (visible.length <= bucketCount) {
    return {
      buckets: visible.map(({ t, value }) => ({
        t,
        min: value,
        max: value,
        average: value,
        count: 1,
      })),
      rawCount: visible.length,
      granularity: 0,
    };
  }

  const first = visible[0]!.t;
  const span = Math.max(1, visible[visible.length - 1]!.t - first);
  const granularity = span / bucketCount;
  const buckets: TimeSeriesBucket[] = [];
  let current: TimeSeriesBucket | null = null;
  let currentIndex = -1;
  let sum = 0;

  for (const { t, value } of visible) {
    const index = Math.min(
      bucketCount - 1,
      Math.floor((t - first) / granularity)
    );
    if (index !== currentIndex) {
      if (current) {
        current.average = sum / current.count;
        buckets.push(current);
      }
      currentIndex = index;
      sum = 0;
      current = {
        t: first + (index + 0.5) * granularity,
        min: value,
        max: value,
        average: value,
        count: 0,
      };
    }
    current!.min = Math.min(current!.min, value);
    current!.max = Math.max(current!.max, value);
    current!.count += 1;
    sum += value;
  }

  if (current) {
    current.average = sum / current.count;
    buckets.push(current);
  }

  return { buckets, rawCount: visible.length, granularity };
}

const byBucketTime = bisector<TimeSeriesBucket, number>((bucket) => bucket.t);

/** The bucket closest to `t`, or undefined for an empty series. */
export function nearestBucket(
  buckets: TimeSeriesBucket[],
  t: number
): TimeSeriesBucket | undefined {
  if (buckets.length === 0) {
    return undefined;
  }
  return buckets[byBucketTime.center(buckets, t)];
}

export interface BreachSummary {
  /** Separate excursions above the threshold. */
  count: number;
  /** Highest raw value in the window. */
  peak: number | undefined;
}

/**
 * Counts raw-point excursions above `threshold` inside the window. Like an
 * alarm deadband, an excursion only ends once the value falls `hysteresis`
 * below the threshold, so sensor noise around the limit counts once.
 */
export function summarizeBreaches(
  points: TimeSeriesPoint[],
  [start, end]: [number, number],
  threshold: number,
  hysteresis = Math.abs(threshold) * 0.02
): BreachSummary {
  const from = byTime.left(points, start);
  const to = byTime.right(points, end);
  let count = 0;
  let above = false;
  let peak: number | undefined;

  for (let index = from; index < to; index += 1) {
    const { value } = points[index]!;
    peak = peak === undefined ? value : Math.max(peak, value);
    if (!above && value > threshold) {
      count += 1;
      above = true;
    } else if (above && value < threshold - hysteresis) {
      above = false;
    }
  }

  return { count, peak };
}

import { cn } from '@cognite/aura/utils';
import { scaleTime, type ScaleTime } from 'd3-scale';
import type { ComponentProps, ReactNode, RefObject } from 'react';
import { createContext, useContext, useId, useMemo, useState } from 'react';

import {
  aggregateSeries,
  type AggregateResult,
} from './time-series-chart.aggregate';
import type { TimeSeries, TimeSeriesEvent } from './time-series-chart.data';
import {
  useElementWidth,
  useTimeZoom,
  type TimeDomain,
} from './time-series-chart.hooks';

const MINUTE = 60_000;

export const PLOT_MARGIN = { top: 22, right: 16, bottom: 28, left: 56 };
const LANE_HEADER = 22;
const LANE_GAP = 14;

export interface TimeSeriesLaneData {
  series: TimeSeries;
  result: AggregateResult;
}

export interface TimeSeriesLayout {
  /** Plot width excluding axis margins. */
  innerWidth: number;
  /** Height of all lanes, excluding the event row and x-axis. */
  plotHeight: number;
  /** Full SVG height. */
  height: number;
  laneHeight: number;
  laneTop: (index: number) => number;
}

function getLayout(
  laneCount: number,
  laneHeight: number,
  width: number
): TimeSeriesLayout {
  const stride = LANE_HEADER + laneHeight + LANE_GAP;
  const plotHeight = Math.max(1, laneCount) * stride - LANE_GAP;
  return {
    innerWidth: Math.max(0, width - PLOT_MARGIN.left - PLOT_MARGIN.right),
    plotHeight,
    height: PLOT_MARGIN.top + plotHeight + PLOT_MARGIN.bottom,
    laneHeight,
    laneTop: (index) => index * stride + LANE_HEADER,
  };
}

function getFullDomain(series: TimeSeries[]): TimeDomain {
  let start = Number.POSITIVE_INFINITY;
  let end = Number.NEGATIVE_INFINITY;
  for (const { points } of series) {
    const first = points[0];
    const last = points[points.length - 1];
    if (first && last) {
      start = Math.min(start, first.t);
      end = Math.max(end, last.t);
    }
  }
  return Number.isFinite(start) ? [start, end] : [0, 24 * 60 * MINUTE];
}

interface TimeSeriesChartContextValue {
  series: TimeSeries[];
  events: TimeSeriesEvent[];
  visibleSeries: TimeSeries[];
  /** Visible series, downsampled for the current window and width. */
  lanes: TimeSeriesLaneData[];
  isSeriesVisible: (id: string) => boolean;
  setSeriesVisible: (id: string, visible: boolean) => void;

  fullDomain: TimeDomain;
  domain: TimeDomain;
  zoomTo: (domain: TimeDomain, options?: { animate?: boolean }) => void;
  zoomBy: (factor: number, anchor?: number) => void;
  panBy: (fraction: number) => void;
  reset: () => void;

  hoverTime: number | null;
  setHoverTime: (time: number | null) => void;

  width: number;
  layout: TimeSeriesLayout;
  /** Buckets per lane: about one per 2 px of plot width. */
  maxBuckets: number;
  x: ScaleTime<number, number>;
  /** Callback ref for the element whose width sizes the chart. */
  plotContainerRef: (element: HTMLDivElement | null) => void;
  zoomTargetRef: RefObject<SVGRectElement | null>;
  summaryId: string;
  hasSummary: boolean;
  setHasSummary: (value: boolean) => void;
}

const TimeSeriesChartContext =
  createContext<TimeSeriesChartContextValue | null>(null);

export function useTimeSeriesChart(): TimeSeriesChartContextValue {
  const context = useContext(TimeSeriesChartContext);
  if (!context) {
    throw new Error(
      'useTimeSeriesChart must be used within a <TimeSeriesChart />'
    );
  }
  return context;
}

export interface TimeSeriesChartProps extends ComponentProps<'div'> {
  /** Series to plot, one lane each. All lanes share the time axis. */
  series: TimeSeries[];
  /** Point or span annotations drawn across every lane. */
  events?: TimeSeriesEvent[];
  /** Height of each lane's plot area in pixels. */
  laneHeight?: number;
  /** Narrowest window people can zoom to, in milliseconds. */
  minSpan?: number;
  /** Series ids hidden on first render. */
  defaultHiddenSeries?: string[];
}

/**
 * Root of a composable D3 time series chart. Holds the shared state — visible
 * window (d3-zoom), hover time, series visibility, layout and downsampled
 * data — and exposes it to every `TimeSeries*` part through context.
 */
export function TimeSeriesChart({
  series,
  events = [],
  laneHeight = 112,
  minSpan = 30 * MINUTE,
  defaultHiddenSeries = [],
  className,
  children,
  ...props
}: TimeSeriesChartProps): ReactNode {
  const summaryId = useId();
  const [plotElement, plotContainerRef] = useState<HTMLDivElement | null>(null);
  const width = useElementWidth(plotElement);
  const [hiddenIds, setHiddenIds] = useState<ReadonlySet<string>>(
    () => new Set(defaultHiddenSeries)
  );
  const [hoverTime, setHoverTime] = useState<number | null>(null);
  const [hasSummary, setHasSummary] = useState(false);

  const fullDomain = useMemo(() => getFullDomain(series), [series]);
  const visibleSeries = useMemo(
    () => series.filter(({ id }) => !hiddenIds.has(id)),
    [series, hiddenIds]
  );
  const layout = getLayout(visibleSeries.length, laneHeight, width);
  const maxBuckets = Math.max(1, Math.floor(layout.innerWidth / 2));

  const { targetRef, domain, zoomTo, zoomBy, panBy, reset } =
    useTimeZoom<SVGRectElement>({
      fullDomain,
      width: layout.innerWidth,
      height: layout.plotHeight,
      minSpan,
    });

  const lanes = useMemo(
    () =>
      visibleSeries.map((item) => ({
        series: item,
        result: aggregateSeries(item.points, domain, maxBuckets),
      })),
    [visibleSeries, domain, maxBuckets]
  );

  const x = scaleTime().domain(domain).range([0, layout.innerWidth]);

  const setSeriesVisible = (id: string, visible: boolean) => {
    setHiddenIds((current) => {
      const next = new Set(current);
      if (visible) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  const value: TimeSeriesChartContextValue = {
    series,
    events,
    visibleSeries,
    lanes,
    isSeriesVisible: (id) => !hiddenIds.has(id),
    setSeriesVisible,
    fullDomain,
    domain,
    zoomTo,
    zoomBy,
    panBy,
    reset,
    hoverTime,
    setHoverTime,
    width,
    layout,
    maxBuckets,
    x,
    plotContainerRef,
    zoomTargetRef: targetRef,
    summaryId,
    hasSummary,
    setHasSummary,
  };

  return (
    <TimeSeriesChartContext.Provider value={value}>
      <div
        data-slot="time-series-chart"
        className={cn('w-full min-w-0', className)}
        {...props}
      >
        {children}
      </div>
    </TimeSeriesChartContext.Provider>
  );
}

/**
 * Sample sensor data for the time series chart: two weeks of one-minute
 * readings for three pump sensors, plus operational events. A seeded PRNG
 * keeps the data identical between renders, builds and test runs.
 */

export interface TimeSeriesPoint {
  /** Epoch milliseconds. */
  t: number;
  value: number;
}

export type SeriesColor = 'fjord' | 'nordic' | 'aurora' | 'dusk' | 'orange';

export interface TimeSeriesThreshold {
  value: number;
  label: string;
}

export interface TimeSeries {
  id: string;
  name: string;
  unit: string;
  color: SeriesColor;
  /** Decimal places used in tooltips and the latest-value label. */
  precision: number;
  points: TimeSeriesPoint[];
  threshold?: TimeSeriesThreshold;
}

export interface TimeSeriesEvent {
  id: string;
  label: string;
  start: number;
  /** Omit for a point-in-time event. */
  end?: number;
}

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

export const sampleEnd = Date.UTC(2026, 8, 28, 0, 0);
export const sampleStart = sampleEnd - 14 * DAY;

const maintenanceStart = sampleEnd - 6 * DAY + 8 * HOUR;
const maintenanceEnd = maintenanceStart + 5 * HOUR;
const pumpTrip = sampleEnd - 2 * DAY - 3 * HOUR;

function mulberry32(seed: number): () => number {
  let state = seed;
  return () => {
    state |= 0;
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface SignalOptions {
  seed: number;
  base: number;
  dailyAmplitude: number;
  noise: number;
  drift: number;
  /** Value while the pump is stopped (maintenance and after a trip). */
  offValue: number;
  /** Extra excursion during the hour before the pump trip. */
  surge?: number;
}

function generateSignal({
  seed,
  base,
  dailyAmplitude,
  noise,
  drift,
  offValue,
  surge = 0,
}: SignalOptions): TimeSeriesPoint[] {
  const random = mulberry32(seed);
  const points: TimeSeriesPoint[] = [];
  let walk = 0;

  for (let t = sampleStart; t <= sampleEnd; t += MINUTE) {
    walk = walk * 0.995 + (random() - 0.5) * drift;
    const phase = ((t % DAY) / DAY) * Math.PI * 2;
    let value =
      base +
      Math.sin(phase - Math.PI / 2) * dailyAmplitude +
      walk +
      (random() - 0.5) * noise;

    const minutesBeforeTrip = (pumpTrip - t) / MINUTE;
    if (minutesBeforeTrip > 0 && minutesBeforeTrip < 60) {
      value += surge * (1 - minutesBeforeTrip / 60);
    }

    const stopped =
      (t >= maintenanceStart && t < maintenanceEnd) ||
      (t >= pumpTrip && t < pumpTrip + 40 * MINUTE);
    if (stopped) {
      value = offValue + (random() - 0.5) * noise * 0.2;
    }

    points.push({ t, value });
  }

  return points;
}

export const sampleSeries: TimeSeries[] = [
  {
    id: 'discharge-pressure',
    name: 'Discharge pressure',
    unit: 'bar',
    color: 'fjord',
    precision: 1,
    threshold: { value: 46, label: 'High alarm' },
