import { scaleTime } from 'd3-scale';
import { select } from 'd3-selection';
import 'd3-transition';
import { zoom, zoomIdentity, type ZoomBehavior } from 'd3-zoom';
import { useCallback, useEffect, useRef, useState } from 'react';

import { auraMotion } from './time-series-chart.tokens';

export type TimeDomain = [number, number];

/**
 * Width of an element, kept in sync with a ResizeObserver. Takes the element
 * itself (from a callback ref) so it re-subscribes when the node changes.
 */
export function useElementWidth(element: Element | null): number {
  const [width, setWidth] = useState(0);

  useEffect(() => {
    if (!element) {
      setWidth(0);
      return;
    }
    const observer = new ResizeObserver(([entry]) => {
      if (entry) {
        setWidth(Math.floor(entry.contentRect.width));
      }
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, [element]);

  return width;
}

function prefersReducedMotion(): boolean {
  return (
    typeof window !== 'undefined' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches
  );
}

interface UseTimeZoomOptions {
  fullDomain: TimeDomain;
  /** Plot width in pixels, excluding axis margins. */
  width: number;
  /** Plot height in pixels; used as the zoom extent. */
  height: number;
  /** Narrowest window people can zoom to, in milliseconds. */
  minSpan: number;
}

/**
 * Owns the visible time window with d3-zoom. The zoom transform is the single
 * source of truth: drag, Ctrl/⌘ + wheel, pinch, double-click, the overview
 * brush and the range presets all end up calling `zoom.transform`, and every
 * zoom event writes the rescaled domain back to React state.
 *
 * Attach `targetRef` to the element that should receive pointer gestures
 * (usually a transparent rect over the plot).
 */
export function useTimeZoom<T extends Element>({
  fullDomain,
  width,
  height,
  minSpan,
}: UseTimeZoomOptions) {
  const targetRef = useRef<T>(null);
  const zoomRef = useRef<ZoomBehavior<T, unknown> | null>(null);
  const [domain, setDomain] = useState<TimeDomain>(fullDomain);
  // Mirrors `domain` for callbacks and the resize effect without making
  // them re-subscribe on every zoom frame.
  const domainRef = useRef(domain);

  const [fullStart, fullEnd] = fullDomain;

  const clampDomain = useCallback(
    ([start, end]: TimeDomain): TimeDomain => {
      const fullSpan = fullEnd - fullStart;
      const span = Math.min(fullSpan, Math.max(minSpan, end - start));
      const center = (start + end) / 2;
      const clampedStart = Math.min(
        fullEnd - span,
        Math.max(fullStart, center - span / 2)
      );
      return [clampedStart, clampedStart + span];
    },
    [fullStart, fullEnd, minSpan]
  );

  const transformFor = useCallback(
    (target: TimeDomain) => {
      const base = scaleTime().domain([fullStart, fullEnd]).range([0, width]);
      const [start, end] = clampDomain(target);
      const k = width / Math.max(1, base(end) - base(start));
      return zoomIdentity.scale(k).translate(-base(start), 0);
    },
    [clampDomain, fullStart, fullEnd, width]
  );

  useEffect(() => {
    const target = targetRef.current;
    if (!target || width <= 0) {
      return;
    }
    const base = scaleTime().domain([fullStart, fullEnd]).range([0, width]);
    const behavior = zoom<T, unknown>()
      .scaleExtent([1, (fullEnd - fullStart) / minSpan])
      .extent([
        [0, 0],
        [width, height],
      ])
      .translateExtent([
        [0, 0],
        [width, height],
      ])
      // Plain wheel scrolls the page; Ctrl/⌘ + wheel (and trackpad pinch,
      // which sets ctrlKey) zooms. Drag, touch and double-click still pan
      // and zoom as usual.
      .filter((event: Event) => {
        if (event.type === 'wheel') {
          const wheel = event as WheelEvent;
          return wheel.ctrlKey || wheel.metaKey;
        }
        const mouse = event as MouseEvent;
        return !mouse.ctrlKey && !mouse.button;
      })
      .on('zoom', (event: { transform: typeof zoomIdentity }) => {
        const [start, end] = event.transform.rescaleX(base).domain();
        const next: TimeDomain = [+start!, +end!];
        domainRef.current = next;
        setDomain(next);
      });

    const selection = select(target).call(behavior);
    // Re-apply the current window after a resize so the transform keeps
    // pointing at the same time range.
    selection.call(behavior.transform, transformFor(domainRef.current));
    zoomRef.current = behavior;

    return () => {
      selection.on('.zoom', null);
      zoomRef.current = null;
    };
  }, [fullStart, fullEnd, width, height, minSpan, transformFor]);

  const zoomTo = useCallback(
    (target: TimeDomain, { animate = true }: { animate?: boolean } = {}) => {
      const element = targetRef.current;
      const behavior = zoomRef.current;
      if (!element || !behavior) {
        return;
      }
      const transform = transformFor(target);
      const selection = select(element);
      if (animate && !prefersReducedMotion()) {
        selection
          .transition()
          .duration(auraMotion.duration)
          .ease(auraMotion.standardEase)
          .call(behavior.transform, transform);
      } else {
        selection.interrupt().call(behavior.transform, transform);
      }
    },
    [transformFor]
  );

  /** Zoom by `factor` (> 1 zooms in) around `anchor`, default the center. */
  const zoomBy = useCallback(
    (factor: number, anchor?: number) => {
      const [start, end] = domainRef.current;
      const pivot = anchor ?? (start + end) / 2;
      zoomTo(
        clampDomain([
          pivot - (pivot - start) / factor,
          pivot + (end - pivot) / factor,
        ]),
        { animate: false }
      );
    },
    [clampDomain, zoomTo]
  );

  /** Pan by a fraction of the visible span (negative pans left). */
  const panBy = useCallback(
    (fraction: number) => {
      const [start, end] = domainRef.current;
      const delta = (end - start) * fraction;
      zoomTo([start + delta, end + delta], { animate: false });
    },
    [zoomTo]
  );

  const reset = useCallback(
    () => zoomTo([fullStart, fullEnd]),
    [fullStart, fullEnd, zoomTo]
  );

  return { targetRef, domain, zoomTo, zoomBy, panBy, reset };
}

import type { SeriesColor } from './time-series-chart.data';

/**
 * Aura chart tokens per series ramp. Classes are written out in full so
 * Tailwind can see them — never build `stroke-chart-${ramp}-color-1` at
 * runtime. Step 1 is the strongest tone (lines, markers); step 5 is a
 * light alpha fill (min/max bands).
 */
export const seriesTokens: Record<
  SeriesColor,
  { line: string; band: string; marker: string; swatch: string }
> = {
  fjord: {
    line: 'stroke-chart-fjord-color-1',
    band: 'fill-chart-fjord-color-5',
    marker: 'fill-chart-fjord-color-1',
    swatch: 'bg-chart-fjord-color-1',
  },
  nordic: {
    line: 'stroke-chart-nordic-color-1',
    band: 'fill-chart-nordic-color-5',
    marker: 'fill-chart-nordic-color-1',
    swatch: 'bg-chart-nordic-color-1',
  },
  aurora: {
    line: 'stroke-chart-aurora-color-1',
    band: 'fill-chart-aurora-color-5',
    marker: 'fill-chart-aurora-color-1',
    swatch: 'bg-chart-aurora-color-1',
  },
  dusk: {
    line: 'stroke-chart-dusk-color-1',
    band: 'fill-chart-dusk-color-5',
    marker: 'fill-chart-dusk-color-1',
    swatch: 'bg-chart-dusk-color-1',
  },
  orange: {
    line: 'stroke-chart-orange-color-1',
    band: 'fill-chart-orange-color-5',
    marker: 'fill-chart-orange-color-1',
    swatch: 'bg-chart-orange-color-1',
  },
};

/**
 * CSS-style cubic-bezier as a d3 easing function (t in [0, 1]). Aura has no
 * motion tokens, but DESIGN.md defines the curves; use them for d3
 * transitions so charts move like the rest of the UI.
 */
function cubicBezier(
  x1: number,
  y1: number,
  x2: number,
  y2: number
): (t: number) => number {
  const sample = (a: number, b: number, t: number) =>
    3 * a * (1 - t) ** 2 * t + 3 * b * (1 - t) * t ** 2 + t ** 3;
  return (x) => {
    if (x <= 0 || x >= 1) {
      return x;
    }
    // Bisect for the curve parameter whose x matches, then return its y.
    let low = 0;
    let high = 1;
    let t = x;
    for (let index = 0; index < 20; index += 1) {
      const current = sample(x1, x2, t);
      if (Math.abs(current - x) < 1e-5) {
        break;
      }
      if (current < x) {
        low = t;
      } else {
        high = t;
      }
      t = (low + high) / 2;
    }
    return sample(y1, y2, t);
  };
}

/** Aura motion: Standard easing and duration for repositioning. */
export const auraMotion = {
  standardEase: cubicBezier(0.4, 0, 0.15, 1),
  duration: 300,
};

import {
  Badge,
  Button,
  Kbd,
  SegmentedControl,
  SegmentedControlButton,
  SegmentedControlList,
  Toggle,
} from '@cognite/aura/components';
import { cn } from '@cognite/aura/utils';
import { IconZoomReset } from '@tabler/icons-react';
import { format } from 'd3-format';
import type { ComponentProps, ReactNode } from 'react';
import { useEffect } from 'react';

import { summarizeBreaches } from './time-series-chart.aggregate';
import { useTimeSeriesChart } from './time-series-chart.context';
import type { TimeDomain } from './time-series-chart.hooks';
import { seriesTokens } from './time-series-chart.tokens';
import { formatTooltipTime, formatWithUnit } from './time-series-plot';

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

export interface TimeSeriesRangePreset {
  value: string;
  label: string;
  /** Window length in milliseconds, ending at the latest reading. */
  span: number;
}

export const defaultRangePresets: TimeSeriesRangePreset[] = [
  { value: '1d', label: '24h', span: DAY },
  { value: '7d', label: '7d', span: 7 * DAY },
  { value: 'all', label: 'All', span: Number.POSITIVE_INFINITY },
];

function matchPreset(
  presets: TimeSeriesRangePreset[],
  [start, end]: TimeDomain,
  [fullStart, fullEnd]: TimeDomain
): string | null {
  const isFull = start - fullStart < MINUTE && fullEnd - end < MINUTE;
  if (fullEnd - end > MINUTE) {
    return null;
  }
  const preset = presets.find((option) =>
    Number.isFinite(option.span)
      ? Math.abs(end - start - option.span) < MINUTE
      : isFull
  );
  return preset?.value ?? null;
}

/** Segmented control that jumps to windows ending at the latest reading. */
export function TimeSeriesRangePresets({
  presets = defaultRangePresets,
}: {
  presets?: TimeSeriesRangePreset[];
}): ReactNode {
  const { domain, fullDomain, zoomTo } = useTimeSeriesChart();
  const active = matchPreset(presets, domain, fullDomain);

  return (
    <SegmentedControl
      value={active}
      onValueChange={(value) => {
        const preset = presets.find((option) => option.value === value);
        if (preset) {
          const [fullStart, fullEnd] = fullDomain;
          zoomTo([Math.max(fullStart, fullEnd - preset.span), fullEnd]);
        }
      }}
    >
      <SegmentedControlList size="small" aria-label="Time range">
        {presets.map((preset) => (
          <SegmentedControlButton key={preset.value} value={preset.value}>
            {preset.label}
          </SegmentedControlButton>
        ))}
      </SegmentedControlList>
    </SegmentedControl>
  );
}

/** Icon button that animates back to the full range. */
export function TimeSeriesResetZoom(): ReactNode {
  const { domain, fullDomain, reset } = useTimeSeriesChart();
  const isFull =
    domain[0] - fullDomain[0] < MINUTE && fullDomain[1] - domain[1] < MINUTE;
  return (
    <Button
      variant="outline"
      size="icon-sm"
      aria-label="Reset zoom"
      title="Reset zoom"
      disabled={isFull}
      onClick={reset}
    >
      <IconZoomReset />
    </Button>
  );
}

/** One toggle per series to show or hide its lane. */
export function TimeSeriesLegend({
  className,
  ...props
}: ComponentProps<'div'>): ReactNode {
  const { series, visibleSeries, isSeriesVisible, setSeriesVisible } =
    useTimeSeriesChart();
  return (
    <div
      role="group"
      aria-label="Visible series"
      data-slot="time-series-legend"
      className={cn('flex flex-wrap items-center gap-1', className)}
      {...props}
    >
      {series.map((item) => {
        const pressed = isSeriesVisible(item.id);
        return (
          <Toggle
            key={item.id}
            variant="outline"
            size="sm"
            pressed={pressed}
            // Keep at least one lane on screen.
            disabled={pressed && visibleSeries.length === 1}
            onPressedChange={(next) => setSeriesVisible(item.id, next)}
          >
            <span
              className={cn(
                'size-2 rounded-full',
                pressed
                  ? seriesTokens[item.color].swatch
                  : 'bg-disabled-foreground'
              )}
            />
            {item.name}
          </Toggle>
        );
      })}
    </div>
  );
}

const formatCount = format(',');

function formatGranularity(ms: number): string {
  if (ms <= 0) {
    return 'Raw readings';
  }
  if (ms < HOUR) {
    return `1 point ≈ ${Math.max(1, Math.round(ms / MINUTE))} min`;
  }
  return `1 point ≈ ${Math.round((ms / HOUR) * 10) / 10} h`;
}

/** Current level of detail and how many raw readings are in view. */
export function TimeSeriesResolution({
  className,
  ...props
}: ComponentProps<'div'>): ReactNode {
  const { lanes } = useTimeSeriesChart();
  const rawInView = lanes.reduce((sum, lane) => sum + lane.result.rawCount, 0);
  return (
    <div
      className={cn(
        'flex items-center gap-2 text-xs text-muted-foreground',
        className
      )}
      {...props}
    >
      <Badge variant="secondary" data-slot="time-series-resolution">
        {formatGranularity(lanes[0]?.result.granularity ?? 0)}
      </Badge>
      <span className="tabular-nums">
        {formatCount(rawInView)} readings in view
      </span>
    </div>
  );
}

/**
 * Text summary of the visible window and threshold breaches. Aura requires a
 * text alternative for every chart; the plot points to this with
 * `aria-describedby`.
 */
export function TimeSeriesSummary({
  className,
  ...props
}: ComponentProps<'div'>): ReactNode {
  const { visibleSeries, domain, summaryId, setHasSummary } =
    useTimeSeriesChart();

  useEffect(() => {
    setHasSummary(true);
    return () => setHasSummary(false);
  }, [setHasSummary]);

  const insights = visibleSeries.flatMap((item) => {
    if (!item.threshold) {
      return [];
    }
    const { count, peak } = summarizeBreaches(
      item.points,
      domain,
      item.threshold.value
    );
    const limit = `${item.threshold.label.toLowerCase()} (${formatWithUnit(item, item.threshold.value)})`;
    if (count === 0) {
      return [`${item.name} stayed below the ${limit} in this window.`];
    }
    return [
      `${item.name} crossed the ${limit} ${count === 1 ? 'once' : `${count} times`}, peaking at ${formatWithUnit(item, peak ?? 0)}.`,
    ];
  });

  return (
    <div
      id={summaryId}
      data-slot="time-series-summary"
      className={cn('text-sm', className)}
      {...props}
    >
      <p className="text-foreground">
        {`Showing ${formatTooltipTime(new Date(domain[0]))} – ${formatTooltipTime(new Date(domain[1]))}.`}
      </p>
      {insights.map((insight) => (
        <p key={insight} className="text-muted-foreground">
          {insight}
        </p>
      ))}
    </div>
  );
}

/** Pointer and keyboard hints. */
export function TimeSeriesKeyboardHints({
  className,
  ...props
}: ComponentProps<'p'>): ReactNode {
  return (
    <p
      className={cn(
        'flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground',
        className
      )}
      {...props}
    >
      <span>Drag to pan</span>
      <span>
        <Kbd>Ctrl</Kbd> / <Kbd>⌘</Kbd> + scroll to zoom
      </span>
      <span>Brush the overview to select a range</span>
      <span>
        <Kbd>←</Kbd> <Kbd>→</Kbd> to inspect
      </span>
    </p>
  );
}

import { cn } from '@cognite/aura/utils';
import { extent } from 'd3-array';
import { axisBottom } from 'd3-axis';
import { brushX, type BrushBehavior, type D3BrushEvent } from 'd3-brush';
import { scaleLinear, scaleTime } from 'd3-scale';
import { select } from 'd3-selection';
import { area, curveMonotoneX } from 'd3-shape';
import type { ReactNode } from 'react';
import { useEffect, useLayoutEffect, useMemo, useRef } from 'react';

import {
  aggregateSeries,
  type TimeSeriesBucket,
} from './time-series-chart.aggregate';
import { PLOT_MARGIN, useTimeSeriesChart } from './time-series-chart.context';
import { seriesTokens } from './time-series-chart.tokens';

const MARGIN = { ...PLOT_MARGIN, top: 4, bottom: 22 };
const HEIGHT = 72;

export interface TimeSeriesOverviewProps {
  /** Series drawn in the strip. Defaults to the first visible series. */
  seriesId?: string;
  className?: string;
}

/**
 * Context strip under the main plot. d3-brush owns the selection rectangle
 * and its handles; React draws the area. Brush events that come from the
 * user (`sourceEvent` set) drive the zoom, and zoom changes move the brush
 * back with `brush.move`, which fires events without a `sourceEvent` — the
 * check that stops the two from looping.
 */
export function TimeSeriesOverview({
  seriesId,
  className,
}: TimeSeriesOverviewProps): ReactNode {
  const {
    series,
    visibleSeries,
    fullDomain,
    domain,
    width,
    maxBuckets,
    zoomTo,
  } = useTimeSeriesChart();
  const source =
    series.find(({ id }) => id === seriesId) ?? visibleSeries[0] ?? series[0];
  const buckets = useMemo(
    () =>
      source
        ? aggregateSeries(source.points, fullDomain, maxBuckets).buckets
        : [],
    [source, fullDomain, maxBuckets]
  );
  const onBrush = (next: [number, number]) => zoomTo(next, { animate: false });

  const brushRef = useRef<SVGGElement>(null);
  const axisRef = useRef<SVGGElement>(null);
  const behaviorRef = useRef<BrushBehavior<unknown> | null>(null);
  const brushingRef = useRef(false);
  const onBrushRef = useRef(onBrush);
  const innerWidth = Math.max(0, width - MARGIN.left - MARGIN.right);
  const innerHeight = HEIGHT - MARGIN.top - MARGIN.bottom;
  const [fullStart, fullEnd] = fullDomain;

  useEffect(() => {
    onBrushRef.current = onBrush;
  }, [onBrush]);

  const x = scaleTime().domain(fullDomain).range([0, innerWidth]);
  const [low = 0, high = 1] = extent(buckets, (bucket) => bucket.average);
  const y = scaleLinear().domain([low, high]).range([innerHeight, 0]);
  const path =
    area<TimeSeriesBucket>()
      .x((bucket) => x(bucket.t))
      .y0(innerHeight)
      .y1((bucket) => y(bucket.average))
      .curve(curveMonotoneX)(buckets) ?? undefined;

  useLayoutEffect(() => {
    if (!axisRef.current) {
      return;
    }
    select(axisRef.current)
      .call(
        axisBottom(x)
          .ticks(Math.max(2, Math.floor(innerWidth / 110)))
          .tickSize(0)
          .tickPadding(8)
      )
      .attr('font-size', null)
      .attr('font-family', null)
      .call((group) => group.select('.domain').remove());
  });

  useEffect(() => {
    const group = brushRef.current;
    if (!group || innerWidth <= 0) {
      return;
    }
    const scale = scaleTime()
      .domain([fullStart, fullEnd])
      .range([0, innerWidth]);
    const behavior = brushX<unknown>()
      .extent([
        [0, 0],
        [innerWidth, innerHeight],
      ])
      .on('start brush end', (event: D3BrushEvent<unknown>) => {
        if (!event.sourceEvent) {
          return;
        }
        brushingRef.current = event.type !== 'end';
        const selection = event.selection as [number, number] | null;
        if (!selection) {
          // A click outside the selection clears it: show everything.
          onBrushRef.current([fullStart, fullEnd]);
          return;
        }
        onBrushRef.current([
          +scale.invert(selection[0]),
          +scale.invert(selection[1]),
        ]);
      });

    const selection = select(group).call(behavior);
    // Swap d3's default grey for Aura chart tokens. Classes beat the
    // presentation attributes d3 sets, so only the opacity needs clearing.
    selection
      .select('.selection')
      .attr('fill-opacity', null)
      .attr('stroke', null)
      .attr(
        'class',
        'selection fill-chart-neutral-color-5 stroke-chart-neutral-color-1'
      );
    behaviorRef.current = behavior;

    return () => {
      selection.on('.brush', null);
      behaviorRef.current = null;
    };
  }, [fullStart, fullEnd, innerWidth, innerHeight]);

  const [start, end] = domain;
  useEffect(() => {
    const group = brushRef.current;
    const behavior = behaviorRef.current;
    if (!group || !behavior || brushingRef.current || innerWidth <= 0) {
      return;
    }
    const scale = scaleTime()
      .domain([fullStart, fullEnd])
      .range([0, innerWidth]);
    // Hide the selection at full range so the whole strip isn't highlighted.
    const isFull = start - fullStart < 60_000 && fullEnd - end < 60_000;
    select(group).call(
      behavior.move,
      isFull ? null : [scale(start), scale(end)]
    );
  }, [start, end, fullStart, fullEnd, innerWidth]);

  if (innerWidth <= 0 || !source) {
    return null;
  }

  return (
    <svg
      width={width}
      height={HEIGHT}
      className={cn('block select-none', className)}
      data-slot="time-series-overview"
      aria-hidden
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <rect
          width={innerWidth}
          height={innerHeight}
          rx={4}
          className="fill-muted-background"
        />
        <path d={path} className={seriesTokens[source.color].band} />
        <g
          ref={axisRef}
          transform={`translate(0,${innerHeight})`}
          className="text-xs text-muted-foreground tabular-nums"
        />
        <g ref={brushRef} data-slot="time-series-brush" />
      </g>
    </svg>
  );
}

import { cn } from '@cognite/aura/utils';
import { extent } from 'd3-array';
import { axisBottom, axisLeft, type Axis, type AxisDomain } from 'd3-axis';
import { format } from 'd3-format';
import { scaleLinear, type ScaleLinear } from 'd3-scale';
import { pointer, select } from 'd3-selection';
import { area, curveMonotoneX, line } from 'd3-shape';
import { timeFormat } from 'd3-time-format';
import type {
  ComponentProps,
  KeyboardEvent,
  PointerEvent,
  ReactNode,
} from 'react';
import {
  createContext,
  useContext,
  useId,
  useLayoutEffect,
  useRef,
} from 'react';

import {
  nearestBucket,
  type TimeSeriesBucket,
} from './time-series-chart.aggregate';
import {
  PLOT_MARGIN,
  useTimeSeriesChart,
  type TimeSeriesLaneData,
} from './time-series-chart.context';
import type { TimeSeries } from './time-series-chart.data';
import { seriesTokens } from './time-series-chart.tokens';

const TOOLTIP_WIDTH = 232;

export const formatTooltipTime = timeFormat('%a %b %-d, %H:%M');

export function formatValue(series: TimeSeries, value: number): string {
  return format(`,.${series.precision}f`)(value);
}

/** Value and unit joined by a no-break space, per Aura content guidelines. */
export function formatWithUnit(series: TimeSeries, value: number): string {
  return `${formatValue(series, value)}\u00a0${series.unit}`;
}

/**
 * Lets d3-axis render ticks into a React-owned <g>. React decides where the
 * axis lives; d3 owns its children. d3 writes `font-size` and `font-family`
 * attributes, so they are cleared to let Aura's type classes apply.
 */
function AxisGroup<Domain extends AxisDomain>({
  axis,
  className,
  ...props
}: Omit<ComponentProps<'g'>, 'ref'> & { axis: Axis<Domain> }): ReactNode {
  const ref = useRef<SVGGElement>(null);

  useLayoutEffect(() => {
    if (!ref.current) {
      return;
    }
    select(ref.current)
      .call(axis)
      .attr('font-size', null)
      .attr('font-family', null)
      .call((group) => group.select('.domain').remove())
      .call((group) => group.selectAll('.tick line').remove());
  });

  return (
    <g
      ref={ref}
      aria-hidden
      className={cn('text-xs text-muted-foreground tabular-nums', className)}
      {...props}
    />
  );
}

/* -------------------------------------------------------------------------- */
/* Plot                                                                       */
/* -------------------------------------------------------------------------- */

export type TimeSeriesPlotProps = Omit<ComponentProps<'div'>, 'ref'>;

/**
 * The focusable plot surface. Renders the SVG, measures the available width,
 * attaches d3-zoom and handles pointer and keyboard inspection. Compose
 * layers inside it: `TimeSeriesEvents`, `TimeSeriesLanes`, axes, crosshair
 * and tooltip.
 */
export function TimeSeriesPlot({
  className,
  children,
  'aria-label': ariaLabel = 'Time series chart',
  ...props
}: TimeSeriesPlotProps): ReactNode {
  const {
    lanes,
    layout,
    width,
    x,
    hoverTime,
    setHoverTime,
    zoomBy,
    panBy,
    reset,
    plotContainerRef,
    zoomTargetRef,
    summaryId,
    hasSummary,
  } = useTimeSeriesChart();
  const { innerWidth, plotHeight, height } = layout;
  const buckets = lanes[0]?.result.buckets ?? [];

  const handlePointerMove = (event: PointerEvent<SVGRectElement>) => {
    const [px] = pointer(event.nativeEvent, event.currentTarget);
    setHoverTime(+x.invert(px));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const stepCursor = (direction: 1 | -1) => {
      if (buckets.length === 0) {
        return;
      }
      const current =
        hoverTime === null
          ? direction === 1
            ? -1
            : buckets.length
          : buckets.indexOf(nearestBucket(buckets, hoverTime)!);
      const next = Math.min(
        buckets.length - 1,
        Math.max(0, current + direction)
      );
      setHoverTime(buckets[next]!.t);
    };

    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowLeft': {
        const direction = event.key === 'ArrowRight' ? 1 : -1;
        if (event.shiftKey) {
          panBy(direction * 0.1);
        } else {
          stepCursor(direction);
        }
        break;
      }
      case 'Home':
        if (buckets[0]) setHoverTime(buckets[0].t);
        break;
      case 'End':
        if (buckets.length) setHoverTime(buckets[buckets.length - 1]!.t);
        break;
      case '+':
      case '=':
        zoomBy(2, hoverTime ?? undefined);
        break;
      case '-':
      case '_':
        zoomBy(0.5, hoverTime ?? undefined);
        break;
      case '0':
        reset();
        break;
      case 'Escape':
        setHoverTime(null);
        break;
      default:
        return;
    }
    event.preventDefault();
  };

  const announcement = (() => {
    const anchor =
      hoverTime === null ? undefined : nearestBucket(buckets, hoverTime);
    if (hoverTime === null || !anchor) {
      return '';
    }
    const values = lanes
      .map(({ series, result }) => {
        const bucket = nearestBucket(result.buckets, hoverTime);
        return bucket
          ? `${series.name} ${formatWithUnit(series, bucket.average)}`
          : null;
      })
      .filter(Boolean)
      .join(', ');
    return `${formatTooltipTime(new Date(anchor.t))}. ${values}.`;
  })();

  return (
    <div
      ref={plotContainerRef}
      data-slot="time-series-plot"
      role="group"
      aria-roledescription="interactive chart"
      aria-label={`${ariaLabel}. Use arrow keys to inspect values, Shift + arrows to pan, plus and minus to zoom, 0 to reset.`}
      aria-describedby={hasSummary ? summaryId : undefined}
      tabIndex={0}
      onKeyDown={handleKeyDown}
      onBlur={() => setHoverTime(null)}
      className={cn(
        'w-full min-w-0 rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring',
        className
      )}
      {...props}
    >
      {innerWidth > 0 && (
        <svg
          width={width}
          height={height}
          className="block overflow-visible select-none"
          aria-hidden
        >
          <g transform={`translate(${PLOT_MARGIN.left},${PLOT_MARGIN.top})`}>
            {children}
            <rect
              ref={zoomTargetRef}
              width={innerWidth}
              height={plotHeight}
              className="cursor-crosshair fill-transparent active:cursor-grabbing"
              data-slot="time-series-zoom-target"
              onPointerMove={handlePointerMove}
              onPointerLeave={() => setHoverTime(null)}
            />
          </g>
        </svg>
      )}
      <p aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Lanes                                                                      */
/* -------------------------------------------------------------------------- */

interface TimeSeriesLaneContextValue extends TimeSeriesLaneData {
  index: number;
  y: ScaleLinear<number, number>;
  tokens: (typeof seriesTokens)[keyof typeof seriesTokens];
  clipId: string;
}

const TimeSeriesLaneContext = createContext<TimeSeriesLaneContextValue | null>(
  null
);

export function useTimeSeriesLane(): TimeSeriesLaneContextValue {
  const context = useContext(TimeSeriesLaneContext);
  if (!context) {
    throw new Error('Lane layers must be used within <TimeSeriesLanes />');
  }
  return context;
}

function laneYScale(
  lane: TimeSeriesLaneData,
  laneHeight: number
): ScaleLinear<number, number> {
  const values = lane.result.buckets.flatMap((bucket) => [
    bucket.min,
    bucket.max,
  ]);
  if (lane.series.threshold) {
    values.push(lane.series.threshold.value);
  }
  const [low = 0, high = 1] = extent(values);
  const pad = low === high ? 1 : 0;
  return scaleLinear()
    .domain([low - pad, high + pad])
    .range([laneHeight, 0])
    .nice(4);
}

/**
 * Renders its children once per visible series, stacked into lanes that
 * share the time axis. Each lane gets its own y-scale from the visible data.
 */
export function TimeSeriesLanes({
  children,
}: {
  children: ReactNode;
}): ReactNode {
  const { lanes, layout } = useTimeSeriesChart();
  const uid = useId().replace(/:/g, '');

  return (
    <>
      <defs>
        <clipPath id={`${uid}-lane`}>
          <rect width={layout.innerWidth} height={layout.laneHeight} />
        </clipPath>
      </defs>
      {lanes.map((lane, index) => (
        <TimeSeriesLaneContext.Provider
          key={lane.series.id}
          value={{
            ...lane,
            index,
            y: laneYScale(lane, layout.laneHeight),
            tokens: seriesTokens[lane.series.color],
            clipId: `${uid}-lane`,
          }}
        >
          <g
            transform={`translate(0,${layout.laneTop(index)})`}
            data-slot="time-series-lane"
            data-series={lane.series.id}
          >
            {children}
          </g>
        </TimeSeriesLaneContext.Provider>
      ))}
    </>
  );
}

/** Series name and unit above the lane. */
export function TimeSeriesLaneLabel(): ReactNode {
  const { series } = useTimeSeriesLane();
  return (
    <text y={-8} className="fill-foreground text-xs font-medium">
      {series.name}
      <tspan className="fill-muted-foreground font-normal">
        {` · ${series.unit}`}
      </tspan>
    </text>
  );
}

/** Horizontal gridlines at the y-axis ticks. */
export function TimeSeriesGrid({ ticks = 3 }: { ticks?: number }): ReactNode {
  const { y } = useTimeSeriesLane();
  const { layout } = useTimeSeriesChart();
  return (
    <g data-slot="time-series-grid">
      {y.ticks(ticks).map((tick) => (
        <line
          key={tick}
          x2={layout.innerWidth}
          y1={y(tick)}
          y2={y(tick)}
          className="stroke-chart-gridlines"
        />
      ))}
    </g>
  );
}

export function TimeSeriesYAxis({ ticks = 3 }: { ticks?: number }): ReactNode {
  const { y } = useTimeSeriesLane();
  return (
    <AxisGroup
      axis={axisLeft(y).ticks(ticks).tickPadding(8).tickFormat(format('~s'))}
    />
  );
}

/** Min/max envelope of each bucket. Hidden when showing raw readings. */
export function TimeSeriesBand({
  className,
}: {
  className?: string;
}): ReactNode {
  const { result, y, tokens, clipId } = useTimeSeriesLane();
  const { x } = useTimeSeriesChart();
  if (result.granularity === 0) {
    return null;
  }
  const path = area<TimeSeriesBucket>()
    .x((bucket) => x(bucket.t))
    .y0((bucket) => y(bucket.min))
    .y1((bucket) => y(bucket.max))
    .curve(curveMonotoneX)(result.buckets);
  return (
    <path
      d={path ?? undefined}
      clipPath={`url(#${clipId})`}
      className={cn(tokens.band, className)}
    />
  );
}

function useAveragePath(): string | undefined {
  const { result, y } = useTimeSeriesLane();
  const { x } = useTimeSeriesChart();
  return (
    line<TimeSeriesBucket>()
      .x((bucket) => x(bucket.t))
      .y((bucket) => y(bucket.average))
      .curve(curveMonotoneX)(result.buckets) ?? undefined
  );
}

/** Bucket averages as a line. */
export function TimeSeriesLine({
  className,
}: {
  className?: string;
}): ReactNode {
  const { tokens, clipId } = useTimeSeriesLane();
  const path = useAveragePath();
  return (
    <path
      d={path}
      fill="none"
      strokeWidth={1.5}
      strokeLinejoin="round"
      clipPath={`url(#${clipId})`}
      className={cn(tokens.line, className)}
    />
  );
}

/**
 * The series threshold as a dashed limit line. The line above it is redrawn
 * in the destructive chart color, clipped to the area above the limit.
 */
export function TimeSeriesThreshold(): ReactNode {
  const { series, y, index } = useTimeSeriesLane();
  const { layout } = useTimeSeriesChart();
  const path = useAveragePath();
  const uid = useId().replace(/:/g, '');
  const threshold = series.threshold;
  if (!threshold) {
    return null;
  }
  const thresholdY = y(threshold.value);
  const clipId = `${uid}-breach-${index}`;

  return (
    <g data-slot="time-series-threshold">
      <clipPath id={clipId}>
        <rect width={layout.innerWidth} height={Math.max(0, thresholdY)} />
      </clipPath>
      <path
        d={path}
        fill="none"
        strokeWidth={1.5}
        strokeLinejoin="round"
        clipPath={`url(#${clipId})`}
        className="stroke-chart-destructive-color-1"
      />
      <line
        x2={layout.innerWidth}
        y1={thresholdY}
        y2={thresholdY}
        strokeDasharray="6 4"
        className="stroke-chart-warning-color-1"
      />
      <text
        x={4}
        y={thresholdY + 12}
        paintOrder="stroke"
        strokeWidth={3}
        className="fill-warning-foreground stroke-card text-xs"
      >
        {`${threshold.label} ${formatValue(series, threshold.value)}`}
      </text>
    </g>
  );
}

/** Marker and label on the newest reading, when it is in view. */
export function TimeSeriesLatestValue(): ReactNode {
  const { series, result, y, tokens } = useTimeSeriesLane();
  const { x, domain, fullDomain } = useTimeSeriesChart();
  const last = result.buckets[result.buckets.length - 1];
  if (!last || domain[1] < fullDomain[1] || x(last.t) <= 0) {
    return null;
  }
  return (
    <g data-slot="time-series-latest">
      <circle
        cx={x(last.t)}
        cy={y(last.average)}
        r={3}
        className={tokens.marker}
      />
      <text
        x={x(last.t) - 6}
        y={y(last.average) - 6}
        textAnchor="end"
        paintOrder="stroke"
        strokeWidth={3}
        className="fill-foreground stroke-card text-xs font-medium tabular-nums"
      >
        {formatValue(series, last.average)}
      </text>
    </g>
  );
}

/** Marker on the bucket under the crosshair. */
export function TimeSeriesHoverMarker(): ReactNode {
  const { result, y, tokens } = useTimeSeriesLane();
  const { x, hoverTime } = useTimeSeriesChart();
  const bucket =
    hoverTime === null ? undefined : nearestBucket(result.buckets, hoverTime);
  if (!bucket) {
    return null;
  }
  return (
    <circle
      cx={x(bucket.t)}
      cy={y(bucket.average)}
      r={4}
      strokeWidth={2}
      className={cn('stroke-card', tokens.marker)}
    />
  );
}

/* -------------------------------------------------------------------------- */
/* Plot-wide layers                                                           */
/* -------------------------------------------------------------------------- */

export function TimeSeriesXAxis(): ReactNode {
  const { x, layout } = useTimeSeriesChart();
  return (
    <AxisGroup
      transform={`translate(0,${layout.plotHeight})`}
      axis={axisBottom<Date>(x)
        .ticks(Math.max(2, Math.floor(layout.innerWidth / 110)))
        .tickPadding(8)}
    />
  );
}

/**
 * Event annotations across all lanes: shaded spans for events with an end,
 * dashed lines for point events. Labels that would overlap are skipped.
 */
export function TimeSeriesEvents(): ReactNode {
  const { events, x, layout } = useTimeSeriesChart();
  const { innerWidth, plotHeight } = layout;
  const uid = useId().replace(/:/g, '');
  let labelEnd = Number.NEGATIVE_INFINITY;

  const visible = events
    .map((event) => ({
      event,
      start: x(event.start),
      end: event.end === undefined ? undefined : x(event.end),
    }))
    .filter(({ start, end }) => (end ?? start) >= 0 && start <= innerWidth)
    .sort((a, b) => a.start - b.start);

  return (
    <g data-slot="time-series-events">
      <clipPath id={`${uid}-events`}>
        <rect
          y={-PLOT_MARGIN.top}
          width={innerWidth}
          height={plotHeight + PLOT_MARGIN.top}
        />
      </clipPath>
      <g clipPath={`url(#${uid}-events)`}>
        {visible.map(({ event, start, end }) => {
          const isSpan = end !== undefined;
          const anchorX = isSpan ? Math.max(start, 0) + 4 : start;
          // Rough text width for collision checks; labels are text-xs.
          const labelWidth = event.label.length * 6.5;
          const labelStart = isSpan ? anchorX : anchorX - labelWidth / 2;
          const showLabel = labelStart > labelEnd + 8;
          if (showLabel) {
            labelEnd = labelStart + labelWidth;
          }
          return (
            <g key={event.id} data-slot="time-series-event">
              {isSpan ? (
                <rect
                  x={start}
                  width={Math.max(1, end - start)}
                  height={plotHeight}
                  className="fill-chart-neutral-color-6"
                />
              ) : (
                <line
                  x1={start}
                  x2={start}
                  y2={plotHeight}
                  strokeDasharray="3 3"
                  className="stroke-chart-neutral-color-1"
                />
              )}
              {showLabel && (
                <text
                  x={anchorX}
                  y={-8}
                  textAnchor={isSpan ? 'start' : 'middle'}
                  className="fill-muted-foreground text-xs"
                >
                  {event.label}
                </text>
              )}
            </g>
          );
        })}
      </g>
    </g>
  );
}

function useAnchorBucket(): TimeSeriesBucket | undefined {
  const { lanes, hoverTime } = useTimeSeriesChart();
  if (hoverTime === null || !lanes[0]) {
    return undefined;
  }
  return nearestBucket(lanes[0].result.buckets, hoverTime);
}

/** Vertical line at the hovered time, snapped to the nearest bucket. */
export function TimeSeriesCrosshair(): ReactNode {
  const { x, layout } = useTimeSeriesChart();
  const anchor = useAnchorBucket();
  if (!anchor) {
    return null;
  }
  return (
    <line
      x1={x(anchor.t)}
      x2={x(anchor.t)}
      y2={layout.plotHeight}
      className="pointer-events-none stroke-muted-foreground"
    />
  );
}

/**
 * One tooltip listing every visible series at the hovered time. Positioned
 * with SVG attributes in a <foreignObject>, and flipped near the right edge.
 */
export function TimeSeriesTooltip(): ReactNode {
  const { lanes, x, layout, hoverTime } = useTimeSeriesChart();
  const anchor = useAnchorBucket();
  if (!anchor || hoverTime === null) {
    return null;
  }
  const crosshairX = x(anchor.t);
  const left =
    crosshairX + 12 + TOOLTIP_WIDTH > layout.innerWidth
      ? Math.max(0, crosshairX - 12 - TOOLTIP_WIDTH)
      : crosshairX + 12;

  return (
    <foreignObject
      x={left}
      y={0}
      width={TOOLTIP_WIDTH}
      height={40 + lanes.length * 40}
      className="pointer-events-none overflow-visible"
    >
      <div
        data-slot="time-series-tooltip"
        className="w-full rounded-lg border bg-popover p-2 text-xs text-popover-foreground shadow-md"
      >
        <p className="mb-1.5 font-medium">
          {formatTooltipTime(new Date(anchor.t))}
        </p>
        <ul className="flex flex-col gap-1.5">
          {lanes.map(({ series, result }) => {
            const bucket = nearestBucket(result.buckets, hoverTime);
            if (!bucket) {
              return null;
            }
            return (
              <li key={series.id} className="flex items-start gap-2">
                <span
                  className={cn(
                    'mt-1 size-2 shrink-0 rounded-full',
                    seriesTokens[series.color].swatch
                  )}
                />
                <span className="min-w-0 flex-1">
                  <span className="flex justify-between gap-2">
                    <span className="truncate text-muted-foreground">
                      {series.name}
                    </span>
                    <span className="font-medium tabular-nums">
                      {formatWithUnit(series, bucket.average)}
                    </span>
                  </span>
                  {bucket.count > 1 && (
                    <span className="block text-right text-muted-foreground tabular-nums">
                      {formatValue(series, bucket.min)}–
                      {formatValue(series, bucket.max)} range
                    </span>
                  )}
                </span>
              </li>
            );
          })}
        </ul>
      </div>
    </foreignObject>
  );
}
